		},
	},
})

Translate("esES", "kum-isha-the-collector", {
	title = "Kum'isha el Coleccionista",
	subtitle = "Buscador de draenetista",
	found = "En el páramo cerca del Alto de los Rapiñadores",
	hint = [=[Busque al exiliado que reúne cristales en el corazón del páramo.]=],
	allegiance = "Los draenei perdidos",
	aliases = { "Kum'isha" },
	sections = {
		{
			title = "Resumen",
			text = [=[Kum'isha el Coleccionista es uno de los draenei perdidos que vagan por las Tierras Devastadas, un exiliado de un pueblo antiguo de un mundo más allá del {link:dark-portal}Portal Oscuro{/link}. Tiene un campamento en el corazón del páramo y reúne draenetista, un cristal de su tierra natal que aún puede encontrarse en la tierra roja. Cree que, con suficiente cantidad, podrá abrir una grieta y llevar a su pueblo a casa.]=],
		},
		{
			title = "Importancia",
			text = [=[Kum'isha es amargado, orgulloso y de lengua rápida. Los humanos y los orcos se quejan cada uno del hedor del otro, observa, pero para su nariz todos los pueblos de este mundo huelen igual, y lo que huele en ellos es codicia. La codicia le costó su hogar, dice, y la codicia pagará su regreso. Comercia de buen grado con sus tesoros con quienes le traen cristales, y los desprecia por aceptar el trato.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Busca draenetista en las Tierras Devastadas, sobre todo las raras esferas perfectas.
• Ha intentado abrir una grieta hacia su tierra natal.
• Paga por cada fragmento de cristal que le traen, y desprecia a quienes los traen.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ninguna crónica cuenta cómo llegaron Kum'isha y sus compañeros a las Tierras Devastadas, ni cuánto tiempo llevan vagando por ellas.]=],
		},
	},
	chapters = {
		{
			title = "La esfera perfecta",
			hint = "Lleve al coleccionista el cristal más raro del páramo.",
			text = [=[Hay draenei que han pasado la vida entera buscando una sola esfera perfecta de draenetista, dijo Kum'isha, y han muerto sin terminar su búsqueda. Cuando pusieron una en sus manos, no podía creerlo. Intentó al instante conjurar un portal a casa. El intento fracasó. No perdió la esperanza. Pidió otra esfera.]=],
		},
		{
			title = "La basura de un draenei",
			hint = "Lleve al coleccionista los fragmentos menores del cristal.",
			text = [=[Los fragmentos imperfectos de draenetista nunca abrirán un camino a casa. Aun así, Kum'isha los acepta, pues pueden servir a su pueblo de otras maneras, y los paga con los tesoros de este mundo, a los que llama basura. Dice las mismas palabras de desprecio a cada vendedor muchas veces al día. Admite que aborrece este mundo.]=],
		},
	},
	mentions = {
		{ text = "Al servicio de Kum'isha" },
		{ text = "Los empeños de Kum'isha" },
		{ text = "Todo cuenta en grandes cantidades" },
		{ text = "La basura de un draenei..." },
	},
})

Translate("esES", "bloodmage-drazial", {
	title = "Mago de sangre Drazial",
	subtitle = "Estudioso de la fuerza de las bestias",
	found = "Justo dentro de la frontera norte de las Tierras Devastadas",
	hint = [=[Hable con el mago de sangre elfo que estudia las bestias del páramo.]=],
	aliases = { "Drazial" },
	sections = {
		{
			title = "Resumen",
			text = [=[El mago de sangre Drazial es un elfo de sangre que estudia las bestias de las Tierras Devastadas junto con su hermana {link:bloodmage-lynnore}Lynnore{/link}. Cree que la energía liberada cuando se abrió el {link:dark-portal}Portal Oscuro{/link} se filtró en las criaturas del páramo y las obligó a cambiar. Estudia sus cuerpos. Las fauces de las hienas Snickerfang, el aguante de los jabalíes y la velocidad de los escorpoks acaban todos en sus ensayos, que convierte en elixires de gran fuerza. Advierte que no carecen de coste.]=],
		},
	},
	mentions = {
		{ text = "Quijadas de Snickerfang" },
		{ text = "La vitalidad de un jabalí" },
		{ text = "El golpeador decisivo" },
	},
	bonds = {
		{ id = "bloodmage-lynnore", name = "Maga de sangre Lynnore", note = "su hermana y colega de estudios" },
	},
})

Translate("esES", "bloodmage-lynnore", {
	title = "Maga de sangre Lynnore",
	subtitle = "Estudiosa de la mente de las bestias",
	found = "Justo dentro de la frontera norte de las Tierras Devastadas",
	hint = [=[Hable con la maga de sangre elfa que estudia la mente de las bestias.]=],
	aliases = { "Lynnore" },
	sections = {
		{
			title = "Resumen",
			text = [=[La maga de sangre Lynnore trabaja junto a su hermano {link:bloodmage-drazial}Drazial{/link} en el borde norte del páramo. Mientras él estudia los cuerpos de las bestias, ella estudia sus mentes y sus espíritus. Los basiliscos de piedra roja, dice, piensan con más astucia que algunos pueblos, y los buitres de algún modo prosperan con la carroña más enferma. Sabe que la mayoría de los eruditos rehúyen su oficio y lo cuentan entre las artes oscuras, no mejor que la magia de los demonios. Eso no la inquieta. Cree que la ruina de la Cié{link:naga}naga{/link} Negra, infestada de demonios, es precisamente el lugar donde puede crecer el estudio de la sangre.]=],
		},
	},
	mentions = {
		{ text = "La mordedura del basilisco" },
		{ text = "El vigor del buitre" },
	},
	bonds = {
		{ id = "bloodmage-drazial", name = "Mago de sangre Drazial", note = "su hermano" },
	},
})

